// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address caller, uint64 value, bytes calldata data) public {
        vm.assume(caller != address(0) && caller != c.Owner());
        vm.deal(caller, value);
        uint256 balBefore = address(c).balance;
        bool ok;
        vm.prank(caller);
        try c.Command{value: value}(address(this), data) { ok = true; } catch { ok = false; }
        uint256 balAfter = address(c).balance;
        assertTrue(!ok || balAfter == balBefore);
    }
}
